import { ORDERS_API_URL } from "@/services/orders";
// Un solo usuario (el negocio), así que el panel no maneja sesiones ni
// tokens con expiración: la clave misma es lo que se manda como
// `Authorization: Bearer <clave>` en cada llamada. Vive en `sessionStorage`
// para que se borre sola al cerrar la pestaña, nunca en `localStorage`.
const STORAGE_KEY = "fmc-panel-key";
const readStoredKey = () => {
    try {
        return sessionStorage.getItem(STORAGE_KEY);
    }
    catch {
        return null;
    }
};
const writeStoredKey = (key) => {
    try {
        sessionStorage.setItem(STORAGE_KEY, key);
    }
    catch {
        // Almacenamiento bloqueado (privado/incógnito): el panel funciona igual,
        // solo vuelve a pedir la clave en la próxima recarga.
    }
};
export const clearStoredAdminKey = () => {
    try {
        sessionStorage.removeItem(STORAGE_KEY);
    }
    catch {
        // no-op
    }
};
export const hasStoredAdminKey = () => readStoredKey() !== null;
export class AdminUnauthorizedError extends Error {
}
const request = async (path, { method = "GET", body, key } = {}) => {
    const token = key !== null && key !== void 0 ? key : readStoredKey();
    if (!token)
        throw new AdminUnauthorizedError("sin clave guardada");
    const response = await fetch(`${ORDERS_API_URL}${path}`, {
        method,
        headers: {
            Authorization: `Bearer ${token}`,
            ...(body ? { "Content-Type": "application/json" } : {}),
        },
        ...(body ? { body: JSON.stringify(body) } : {}),
    });
    if (response.status === 401) {
        clearStoredAdminKey();
        throw new AdminUnauthorizedError("clave inválida");
    }
    if (!response.ok) {
        throw new Error(`admin ${response.status}`);
    }
    return (await response.json());
};
/** Prueba la clave contra el backend y, si es válida, la guarda para el resto de la pestaña. */
export const loginToPanel = async (key) => {
    try {
        await request("/admin/orders?limit=1", { key });
        writeStoredKey(key);
        return true;
    }
    catch (error) {
        if (error instanceof AdminUnauthorizedError)
            return false;
        throw error;
    }
};
export const logoutOfPanel = () => clearStoredAdminKey();
export const fetchOrders = (params = {}) => {
    const search = new URLSearchParams();
    if (params.q)
        search.set("q", params.q);
    if (params.status)
        search.set("status", params.status);
    const qs = search.toString();
    return request(`/admin/orders${qs ? `?${qs}` : ""}`);
};
export const fetchOrderDetail = (id) => request(`/admin/orders/${encodeURIComponent(id)}`);
export const updateOrderStatus = (id, status) => request(`/admin/orders/${encodeURIComponent(id)}/status`, {
    method: "PATCH",
    body: { status },
});
export const fetchCustomers = (params = {}) => {
    const search = new URLSearchParams();
    if (params.q)
        search.set("q", params.q);
    if (params.marketing)
        search.set("marketing", params.marketing);
    const qs = search.toString();
    return request(`/admin/customers${qs ? `?${qs}` : ""}`);
};
export const fetchCustomerDetail = (id) => request(`/admin/customers/${id}`);
export const optOutCustomer = (id) => request(`/admin/customers/${id}/opt-out`, { method: "PATCH" });
// No es un borrado: anonimiza la ficha y borra los mensajes de contacto, pero
// los pedidos se conservan por el deber contable. De ahí el verbo PATCH.
export const suppressCustomer = (id) => request(`/admin/customers/${id}/suppress`, { method: "PATCH" });
export const fetchContactMessages = () => request("/admin/contact-messages");
export const updateContactMessageStatus = (id, status) => request(`/admin/contact-messages/${id}/status`, {
    method: "PATCH",
    body: { status },
});
